        ["phykit", "parsimony_informative_sites", str(path)],
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            "PhyKit failed for %s (exit %s): %s"
            % (path.name, proc.returncode, proc.stderr[-2000:])
